/// <summary>
/// MPJ_3173 - nciantar - 09/04/2021
/// Parameter to include number of tasks.
/// </summary>
public class METCustIntStockTransferService extends SysOperationServiceBase
{
    LedgerJournalTable      journalHeader;
    RecordInsertList        ledgerJournalTransList;

}

Method.Source:
    /// <summary>
    /// MPJ_3173 - nciantar - 09/04/2021
    /// Process the operation of the batch job and creates a header and line accordinly
    /// </summary>
    /// <param name = "_dataContract">object of data</param>
    public void processOperation(METCustIntStockTransferContract _dataContract)
    {        
        //CustTable               custTable;
        METCustTable            metCustTable;   
        boolean                 flag;
        LedgerJournalId         journalId;
        LedgerJournalCheckPost  ledgerJournalCheckPost;

        flag = true;

        try
        {     
            while select metCustTable
                where metCustTable.InternalCustomerDimension != 0
            //while select custTable 
            //    join metCustTable 
            //        where custTable.AccountNum == metCustTable.AccountNum
            //        && metCustTable.InternalCustomerDimension != 0
            {
                if (flag)
                {
                    journalId = this.createJournalTable(_dataContract.getLedgerName());  
                    flag = false;
                }            
                this.createJournalLines(journalId,_dataContract.getLedgerName(), 
                                        metCustTable.InternalCustomerDimension,
                                        metCustTable.AccountNum);
            }

            if (journalHeader)
            {
                ledgerJournalTransList.insertDatabase();

                //Validating the journal
                ledgerJournalCheckPost = ledgerJournalCheckPost::newLedgerJournalTable(journalHeader, NoYes::Yes);

                //Posting the journal
                ledgerJournalCheckPost.runOperation();
            }
        }
        catch
        {
            info ("@MET:PopulateCustCreditErrorHandler");
        }


        
    }

    /// <summary>
    /// MPJ_3173 - nciantar - 09/04/2021
    /// Gets total AmountMST (Balance)
    /// </summary>
    /// <param name = "_AccountNum">Cust account num</param>
    /// <returns>total amount mst</returns>
    public AmountMST getBalance(AccountNum _AccountNum)
    {
        CustTrans   custTrans;
        SalesTable  salesTable;

        select sum(AmountMST) from custTrans
            where custTrans.AccountNum == _AccountNum;

        select sum(Estimate) from salesTable
            where salesTable.custAccount == _AccountNum;

        return custTrans.AmountMST + salesTable.Estimate;
    }

/// <summary>
/// MPJ_3173 - nciantar - 09/04/2021
/// Returns a header
/// </summary>
/// <param name = "_ledgerJournalName">ledger jorunal name</param>
/// <returns>header</returns>
public LedgerJournalId createJournalTable(LedgerJournalNameId _ledgerJournalName)
{ 
    
    journalHeader.initValue();
    journalHeader.initFromLedgerJournalName(_ledgerJournalName);
    journalHeader.JournalNum =  JournalTableData::newTable(journalHeader).nextJournalId();
    journalHeader.Name = strFmt("@MET:JournalHeaderName", DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    journalHeader.insert();
              
    return   journalHeader.JournalNum;
}

    /// <summary>
    /// MPJ_3173 - nciantar - 09/04/2021
    /// Creates lines for the header
    /// </summary>
    /// <param name = "_journalId">jorunal id</param>
    /// <param name = "_ledgerJournalName"> ledger journal name</param>
    /// <param name = "_offsetAccount">off set account</param>
    /// <param name = "_accountNum">account number</param>
    public void createJournalLines(LedgerJournalId _journalId, LedgerJournalNameId _ledgerJournalName, DimensionDynamicAccount _offsetAccount, accountNum _accountNum)
    {
        LedgerJournalTrans      transJournal;        
        NumberSeq               numberseq;
        Voucher                 voucherNum;
        AmountMST               balace;


        //Get the specified Journal Name
        LedgerJournalName   ledgerJournalName = LedgerJournalName::find(_ledgerJournalName);

        ledgerJournalTransList = new RecordInsertList(transJournal.TableId);

        numberseq = NumberSeq::newGetVoucherFromCode(NumberSequenceTable::find(ledgerJournalName.NumberSequenceTable).NumberSequence);
        voucherNum = numberseq.voucher();

       
        transJournal.clear();
        transJournal.initValue();
        transJournal.JournalNum             =  _journalId;
        transJournal.TransDate              =  DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        transJournal.AccountType            =  LedgerJournalACType::Cust;
        transJournal.LedgerDimension        = LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(_accountNum, LedgerJournalACType::Cust);
        transJournal.OffsetAccountType      = LedgerJournalACType::Ledger;
        transJournal.OffsetLedgerDimension  = _offsetAccount;
        transJournal.CurrencyCode           = METConstants::currencyCodeAUD;
        transJournal.TaxGroup               = METConstants::taxGroupGSTFree;

        balace = this.getBalance(_accountNum);
         
        if(balace > 0)
        {
            transJournal.AmountCurCredit    = balace;
        }
        else
        {
            transJournal.AmountCurDebit     = balace;
        }
        transJournal.Txt                    = METConstants::offsetTxtInternalStock;
        transJournal.OffsetTxt              = METConstants::offsetTxtInternalStock;
        transJournal.Approved               = NoYes::Yes;
        transJournal.Approver               = HcmWorker::userId2Worker(curuserid());
        transJournal.Voucher                = voucherNum;


        transJournal.SkipBlockedForManualEntryCheck  = true;
        transJournal.defaultRow();
        if (balace != 0)
        {
            ledgerJournalTransList.add(transJournal);
        }

        
        numberseq.used();

    }
